                    "NumberOfColumns": 2,
                    "ColumnContents": [
                      "Name",
                      "Value"
                    ]
                  },
                  "ShowAtMost": 1
                },
                "Information": [
                  {
                    "ReferenceNumber": 45,
                    "Name": "Note",
                    "Value": {
                      "StringWithMarkup": [
                        {
                          "String": "This chemical does not meet GHS hazard criteria for 98.7% (222 of 225) of all reports.",
